INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (113, 'onboarding.identity.address_label', 'onboarding', 'تسمية العنوان الفرعيّ', 'string', 'العنوان الفرعيّ (المنطقة والشارع)', 'العنوان الفرعيّ (المنطقة والشارع)', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (114, 'onboarding.instructions.title', 'onboarding', 'عنوان صفحة التعليمات', 'string', 'تعليمات المنصّة', 'تعليمات المنصّة', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (115, 'onboarding.instructions.html', 'onboarding', 'محتوى صفحة التعليمات (HTML: نصوص وصور وفيديو)', 'text', '<h2>أهلًا بيك 👋</h2><p>قبل ما تبدأ، خُد دقيقتين تعرف المكان اللي إنت داخله وقوانينه.</p><h3>احترام أوّلًا</h3><p>كلّ اللي هنا زمايل. التعامل باحترام شرط بقاء، مش نصيحة.</p><h3>مجهودك ملكك</h3><p>شهاداتك ونقاطك بتتبني على شغلك إنت — والانتحال بيلغي الشهادة.</p><h3>التفعيل مجّانيّ</h3><p>مافيش رسوم تفعيل ولا اشتراك. حسابك بيتفعّل باعتماد من الإدارة بس.</p>', '<h2>أهلًا بيك 👋</h2><p>قبل ما تبدأ، خُد دقيقتين تعرف المكان اللي إنت داخله وقوانينه.</p><h3>احترام أوّلًا</h3><p>كلّ اللي هنا زمايل. التعامل باحترام شرط بقاء، مش نصيحة.</p><h3>مجهودك ملكك</h3><p>شهاداتك ونقاطك بتتبني على شغلك إنت — والانتحال بيلغي الشهادة.</p><h3>التفعيل مجّانيّ</h3><p>مافيش رسوم تفعيل ولا اشتراك. حسابك بيتفعّل باعتماد من الإدارة بس.</p>', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (116, 'onboarding.instructions.scroll_label', 'onboarding', 'زرّ التمرير لأسفل', 'string', 'كمّل قراية ↓', 'كمّل قراية ↓', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
