INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (120, 'onboarding.placement.title', 'onboarding', 'عنوان الاختبار التمهيديّ', 'string', 'اختبار تمهيديّ سريع', 'اختبار تمهيديّ سريع', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (121, 'onboarding.placement.intro_html', 'onboarding', 'مقدّمة الاختبار التمهيديّ (HTML)', 'text', '<p>مافيش رسوب هنا — ده مجرّد تعارف عشان نعرف نبدأ معاك منين. وكلّ سؤال ليه مكافأة.</p>', '<p>مافيش رسوب هنا — ده مجرّد تعارف عشان نعرف نبدأ معاك منين. وكلّ سؤال ليه مكافأة.</p>', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (122, 'onboarding.placement.submit_label', 'onboarding', 'زرّ تسليم الاختبار', 'string', 'سلّم إجاباتي', 'سلّم إجاباتي', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
