INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (126, 'onboarding.review.html', 'onboarding', 'محتوى صفحة «تحت المراجعة» (HTML)', 'text', '<p>سجّلت بنجاح — والتفعيل <strong>مجّانيّ</strong> وبيتمّ باعتماد من الإدارة. هنبلّغك أوّل ما يتفعّل.</p>', '<p>سجّلت بنجاح — والتفعيل <strong>مجّانيّ</strong> وبيتمّ باعتماد من الإدارة. هنبلّغك أوّل ما يتفعّل.</p>', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (127, 'onboarding.accepted.title', 'onboarding', 'عنوان صفحة القبول', 'string', 'تمّ قبول حسابك 🎉', 'تمّ قبول حسابك 🎉', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
INSERT INTO "settings" ("id", "key", "group", "label_ar", "type", "value", "default_value", "hint", "is_sensitive", "is_owner_only", "created_at", "updated_at") VALUES (128, 'onboarding.accepted.html', 'onboarding', 'محتوى صفحة القبول (HTML يضيفه الأدمن)', 'text', '<p>أهلًا بيك رسميًّا معانا. حسابك بقى مفعَّل، وكلّ حاجة في المنصّة بقت قدّامك.</p>', '<p>أهلًا بيك رسميًّا معانا. حسابك بقى مفعَّل، وكلّ حاجة في المنصّة بقت قدّامك.</p>', NULL, 0, 0, '2026-08-06 09:24:58', '2026-08-06 09:24:58');
